#[must_use]
pub fn get_template_bytes(path: &str) -> Option<&'static [u8]> {
    TEMPLATE_INDEX
        .binary_search_by_key(&path, |&(key, _)| key)
        .ok()
        .map(|i| TEMPLATE_DATA[TEMPLATE_INDEX[i].1])
}
